/*
 * N-Tranced's ROM 0x0852D868-0x085346AC: the pause screen's and the
 * continue prompt's graphics, the four struct bg_package pictures' palettes
 * (each the palette of its picture's PNG), then their tiles, then their
 * maps (docs/graphics.md "Menu and title pictures"). The pause screen is
 * N-Tranced's own (games/n2/graphics/menus/pause.png); the continue
 * prompt's three are XS's (graphics/menus/continue_prompt/), the same
 * bytes.
 * Each graphic is a class of graphics.hpp, as in XS's menu_graphics.cpp;
 * the definitions are generated by tools/gfx_manifest.py from
 * games/n2/graphics/manifest.json, in ROM order (docs/n_tranced.md,
 * "Graphics"). Every asset is an LZ77 stream (gbagfx) that starts on a
 * word boundary, hence aligned(4).
 * Linked in ROM order between the incbin'd data by games/n2/ldscript.txt.
 */
#include "menu_graphics.inc"
